-- VNV Events Pasta Station location cycle, local batch 01 (cities 2-15).
SET NAMES utf8mb4;
DELIMITER $$
DROP PROCEDURE IF EXISTS vnv_pasta_b01_preflight$$
CREATE PROCEDURE vnv_pasta_b01_preflight() BEGIN
IF DATABASE()<>'ophyra' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Wrong local database'; END IF;
IF (SELECT COUNT(*) FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-pembroke-pines','pasta-station-catering-miramar','pasta-station-catering-davie','pasta-station-catering-sunrise','pasta-station-catering-surfside','pasta-station-catering-bal-harbour','pasta-station-catering-bay-harbor-islands','pasta-station-catering-miami-springs','pasta-station-catering-virginia-gardens','pasta-station-catering-medley','pasta-station-catering-el-portal','pasta-station-catering-biscayne-park','pasta-station-catering-indian-creek-village','pasta-station-catering-boca-raton'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta content collision'; END IF;
IF (SELECT COUNT(*) FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-pembroke-pines/','/locations/pasta-station-catering-miramar/','/locations/pasta-station-catering-davie/','/locations/pasta-station-catering-sunrise/','/locations/pasta-station-catering-surfside/','/locations/pasta-station-catering-bal-harbour/','/locations/pasta-station-catering-bay-harbor-islands/','/locations/pasta-station-catering-miami-springs/','/locations/pasta-station-catering-virginia-gardens/','/locations/pasta-station-catering-medley/','/locations/pasta-station-catering-el-portal/','/locations/pasta-station-catering-biscayne-park/','/locations/pasta-station-catering-indian-creek-village/','/locations/pasta-station-catering-boca-raton/'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta route collision'; END IF;
END$$
CALL vnv_pasta_b01_preflight()$$
DROP PROCEDURE vnv_pasta_b01_preflight$$
DELIMITER ;
SELECT id INTO @vnv_template_id FROM cms_templates WHERE id_owner=2 AND site_key='vnvevents' AND template_key='local-location-page' AND status='ACTIVE' LIMIT 1;
SELECT id INTO @vnv_category_id FROM cms_categories WHERE id_owner=2 AND site_key='vnvevents' AND slug='catering-services' AND is_active=1 AND applies_to_locations=1 LIMIT 1;
START TRANSACTION;
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
COMMIT;
SELECT COUNT(*) AS pasta_batch_01_contents FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-pembroke-pines','pasta-station-catering-miramar','pasta-station-catering-davie','pasta-station-catering-sunrise','pasta-station-catering-surfside','pasta-station-catering-bal-harbour','pasta-station-catering-bay-harbor-islands','pasta-station-catering-miami-springs','pasta-station-catering-virginia-gardens','pasta-station-catering-medley','pasta-station-catering-el-portal','pasta-station-catering-biscayne-park','pasta-station-catering-indian-creek-village','pasta-station-catering-boca-raton');
SELECT COUNT(*) AS pasta_batch_01_routes FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-pembroke-pines/','/locations/pasta-station-catering-miramar/','/locations/pasta-station-catering-davie/','/locations/pasta-station-catering-sunrise/','/locations/pasta-station-catering-surfside/','/locations/pasta-station-catering-bal-harbour/','/locations/pasta-station-catering-bay-harbor-islands/','/locations/pasta-station-catering-miami-springs/','/locations/pasta-station-catering-virginia-gardens/','/locations/pasta-station-catering-medley/','/locations/pasta-station-catering-el-portal/','/locations/pasta-station-catering-biscayne-park/','/locations/pasta-station-catering-indian-creek-village/','/locations/pasta-station-catering-boca-raton/') AND status='ACTIVE';
